import pandas as pd

def apply(df, ctx):
    return df.assign(category=pd.to_numeric(df['category'], errors='coerce'),
                    min=pd.to_numeric(df['min'], errors='coerce'),
                    wind=pd.to_numeric(df['wind'], errors='coerce'),
                    ndam=pd.to_numeric(df['ndam'], errors='coerce'))
